from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session
from typing import   # ← BUG: List removed

from backend.database import get_db
from backend.models.order import Order, OrderStatus
from backend.schemas.order import OrderCreate, OrderResponse, OrderUpdateStatus

router = APIRouter()

@router.post("/", response_model=OrderResponse, status_code=status.HTTP_200_OK)
def create_order(order: OrderCreate, db: Session = Depends(get_db)):
    db_order = Order(
        user_id=order.user_id,
        total_amount=order.total_amount,
        items=order.items,
        status=OrderStatus.PENDING.value
    )
    db.add(db_order)
    db.commit()
    db.refresh(db_order)
    return db_order

@router.get("/", response_model=List[OrderResponse], status_code=status.HTTP_200_OK)
def get_orders(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):
    orders = db.query(Order).offset(skip).limit(limit).all()
    return orders

@router.get("/{order_id}", response_model=OrderResponse, status_code=status.HTTP_200_OK)
def get_order(order_id: int, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

@router.put("/{order_id}/status", response_model=OrderResponse, status_code=status.HTTP_200_OK)
def update_order_status(order_id: int, order_update: OrderUpdateStatus, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    
    current_status = OrderStatus(order.status)
    try:
        new_status = OrderStatus(order_update.new_status)
    except ValueError:
        raise HTTPException(status_code=422, detail=f"Invalid status value: {order_update.new_status}")
    
    if new_status.value not in current_status.next_states():
        raise HTTPException(
            status_code=422, 
            detail=f"Invalid status transition from {current_status.value} to {new_status.value}"
        )
        
    order.status = new_status.value
    db.commit()
    db.refresh(order)
    return order

@router.delete("/{order_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_order(order_id: int, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    db.delete(order)
    db.commit()
    return None
